import{_ as t,o as n,c as r,j as e,a as l}from"./chunks/framework.QQy01QNh.js";const h=JSON.parse('{"title":"D.20　国家能力、政策执行与治理","description":"","frontmatter":{"title":"D.20　国家能力、政策执行与治理"},"headers":[],"relativePath":"theory/appendix-d/d-20.md","filePath":"theory/appendix-d/d-20.md"}'),o={name:"theory/appendix-d/d-20.md"};function s(d,a,p,i,c,u){return n(),r("div",null,[...a[0]||(a[0]=[e("div",{class:"theory-source"},[e("h1",{id:"section-d-20",tabindex:"-1"},[l("D.20　国家能力、政策执行与治理 "),e("a",{class:"header-anchor",href:"#section-d-20","aria-label":'Permalink to "D.20　国家能力、政策执行与治理 {#section-d-20}"'},"​")]),e("p",null,"正文连接：§7.3.7—7.3.8；§10—11；§14；§15.3.5。研究入口：20.01—20.10。"),e("p",null,"国家形成、财政军事动员、行政自主、嵌入、支配合法性、社会认同与公共服务并非同一过程。服从可以有多种原因，行政到达可以与权利缺口并存。国家能力应落实到具体任务、层级和组织资源，不以一个总强弱尺度替代分析。"),e("p",null,"政策链可以分为问题进入议程、规则制定、资格界定、预算落实、一线执行、通知申请、核定给付、实际使用和申诉纠错。每一环有不同分母与时间。资格者、申请者、获批者和实际领取者的比率不能混算；计算规则使用家庭还是个人单位，也可能改变结果。"),e("p",null,"一线裁量既可弥补规则不适配，也可形成偏差和排斥，须结合任务冲突、资源与监督。多中心治理需要真实的权限与协调，不是机构数量多；反腐与监督要查谁任命、谁支付、谁选择样本、谁有执行和复核权。地方知识的价值不等当地强者代表所有居民。"),e("p",null,"教学例：随机检查促使记录更完整，但对普通申请人的救济仍慢。监督效果与个案救济各有成立范围。临时援助也可以真实改善生活，同时留下财政接续与选择权问题。制度外部性需明确被哪种决策核算排除，不要求先有终局法律责任才能记录损害。"),e("p",null,"自主性须注明相对谁以及对什么：免于政党控制、行政规则裁量、地方或使用者改规权并非同一轴。上级联系可以提供资源与救济，也可能控制目标和个案。批准率、曾领取比例和持续可用服务具有不同分母与时间条件；已经观察到的局部改善应保留，资格总体的覆盖则不能由程序内成功者补齐。"),e("p",null,"专题定位：20.01 国家形成与财政军事国家：Tilly 等；20.02 合法性、支配与国家认同：Weber 等；20.03 国家能力、自主性与嵌入：Mann、Evans、Fukuyama 等；20.04 街头官僚与政策执行：Lipsky；20.05 多中心治理与公地：Ostrom；20.06 公共政策、实施与反馈；20.07 中央地方关系与尺度；20.08 腐败、俘获与委托代理；20.09 民主、威权、官僚与技术治理比较；20.10 治理失败、国家脆弱与重建。")],-1)])])}const f=t(o,[["render",s]]);export{h as __pageData,f as default};
